/* Locus — compact professional tokens (P-22 Signal over Chrome, H-13 Structured Density) */
:root {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --surface-2: #f9fafb;
  --line: #e3e8ee;
  --ink: #1a2430;
  --muted: #5c6b7a;
  --faint: #8a97a5;
  --accent: #1a66e0;
  --accent-ink: #0f4db3;
  --accent-bg: #eaf1fd;
  --accent-line: #bcd4f7;
  --mark: #ffe9a8;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --radius: 6px;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font: 13px/1.45 "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
