.chips {
  flex: none; display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  padding: 7px 14px; background: var(--surface); border-bottom: 1px solid var(--line);
}
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  height: 24px; padding: 0 8px; border-radius: 12px;
  background: var(--accent-bg); border: 1px solid var(--accent-line);
  color: var(--accent-ink); font-size: 12px;
