}
.facet-note { font-weight: 400; text-transform: none; letter-spacing: 0; color: var(--faint); font-size: 10px; }
.facet-row {
  display: flex; align-items: center; width: 100%; gap: 6px;
  padding: 4px 8px; border-radius: 5px; text-align: left;
  color: var(--ink);
}
.facet-row:hover { background: var(--surface-2); }
.facet-row.on { background: var(--accent-bg); color: var(--accent-ink); font-weight: 600; }
.facet-label { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.facet-n { font-size: 11px; color: var(--faint); font-variant-numeric: tabular-nums; }
.facet-row.on .facet-n { color: var(--accent-ink); }
.facet-none { color: var(--faint); font-size: 12px; padding: 2px 8px; }
