  ITEMS.forEach(function (it) {
    it._ts = Date.parse(it.updated);
    it._h = (it.name + " " + it.id + " " + it.tags.join(" ") + " " + it.subcategory + " " +
             it.domain + " " + it.description).toLowerCase();
