    return safe.replace(re, "<mark>$1</mark>");
  }
  function fmtDate(iso) {
    var m = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var p = iso.split("-");
    return m[+p[1] - 1] + " " + p[0];
