  els.results.addEventListener("click", function (e) {
    var row = e.target.closest(".row");
    if (row) select(row.dataset.id);
  });

  function oneOf(set, key, kind) { // toggle helper
    if (set.has(key)) set.delete(key); else set.add(key);
