    else if (k === "domain") state.domains.delete(v);
    else if (k === "subcat") state.subcats.delete(v);
    else if (k === "tags") state.tags.delete(v);
    else if (k === "formats") state.formats.delete(v);
    else if (k === "licenses") state.licenses.delete(v);
