    var inInput = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if (e.key === "/" && !inInput) { els.search.focus(); els.search.select(); e.preventDefault(); }
    else if (e.key === "Escape" && state.sel && !inInput) closeDetail();
