      var sk = it.domainId + "::" + it.subcategory;
      c.subcats[sk] = (c.subcats[sk] || 0) + 1;
      c.licenses[it.license] = (c.licenses[it.license] || 0) + 1;
      for (var f = 0; f < it.formats.length; f++) c.formats[it.formats[f]] = (c.formats[it.formats[f]] || 0) + 1;
