1	/* Locus — app logic.
2	 * Single-owner state { query, category, tags, formats, licenses, selection, expanded }.
3	 * Synchronous boot: data is inline, so first render happens in the same tick —
4	 * the measurable state at page load is `ready`, never `loading`.
5	 */
6	(function () {
7	  "use strict";
8	
9	  var ITEMS = window.LOCUS_ITEMS;
10	  var META = window.LOCUS_META;
11	  var ROW_H = 32, OVERSCAN = 8;
12	
13	  /* ---------- state ---------- */
14	  var state = {
15	    q: "",
16	    domains: new Set(),      // domain ids
17	    subcats: new Set(),      // "domainId::subcategory"
18	    tags: new Set(),
19	    formats: new Set(),
20	    licenses: new Set(),
21	    sel: null,               // selected item id (detail panel)
22	    cursor: 0,               // keyboard cursor = index into filtered
23	    expanded: new Set(),     // expanded tree domains
24	    showAllTags: false
25	  };
26	
27	  var filtered = ITEMS.slice();
28	  var rendered = { start: -1, end: -1 };
29	
30	  /* ---------- boot-time indexes ---------- */
31	  ITEMS.forEach(function (it) {
32	    it._ts = Date.parse(it.updated);
33	    it._h = (it.name + " " + it.id + " " + it.tags.join(" ") + " " + it.subcategory + " " +
34	             it.domain + " " + it.description).toLowerCase();
35	    it._nl = it.name.toLowerCase();
36	  });
37	  var byId = Object.create(null);
38	  ITEMS.forEach(function (it) { byId[it.id] = it; });
39	
40	  /* ---------- tiny DOM helpers ---------- */
41	  function $(id) { return document.getElementById(id); }
42	  var els = {
43	    app: $("app"), search: $("search"), count: $("result-count"), clearAll: $("clear-all"),
44	    chips: $("chips"), tree: $("tree"), tags: $("tag-facets"), formats: $("format-facets"),
45	    licenses: $("license-facets"), results: $("results"), empty: $("empty"),
46	    emptyDetail: $("empty-detail"), emptyClear: $("empty-clear"), detail: $("detail"),
47	    dCrumb: $("d-crumb"), dName: $("d-name"), dId: $("d-id"), dDesc: $("d-desc"),
