/* Evidence capture for Locus (cell-j02-s02-b).
 * Drives the real app in headless Chrome via CDP: real key events, real clicks,
 * screenshots per step + machine-readable observation log. Dev tooling only —
 * not part of the deliverable.
 */
const puppeteer = require("puppeteer-core");
const fs = require("fs");
const path = require("path");

const CHROME = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const FILE = "file:///E:/codex-prj/ab-worktrees/pi-matrix/cell-j02-s02-b/index.html";
const OUT = path.join(__dirname, "..", "evidence");

const log = [];
function rec(step, k, v) {
  log.push({ step, k, v: typeof v === "object" ? JSON.stringify(v) : String(v) });
  console.log(`[${step}] ${k} = ${typeof v === "object" ? JSON.stringify(v) : v}`);
}
async function shot(page, name) {
  await page.screenshot({ path: path.join(OUT, name), type: "png" });
  rec(name, "screenshot", path.join(OUT, name));
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await puppeteer.launch({
    executablePath: CHROME,
    headless: "new",
    args: ["--disable-gpu", "--force-device-scale-factor=1"],
    defaultViewport: { width: 1600, height: 1000 },
  });
  const page = await browser.newPage();
  const consoleMsgs = [];
  page.on("console", (m) => consoleMsgs.push({ type: m.type(), text: m.text() }));
  page.on("pageerror", (e) => consoleMsgs.push({ type: "pageerror", text: String(e) }));

  const state = () => page.$eval("#app", (a) => a.dataset.state);
  const counter = () => page.$eval("#result-count", (e) => e.textContent.trim());
  const chips = () => page.$$eval("#chips .chip", (cs) => cs.map((c) => c.textContent.trim()));
  const scrollTop = () => page.$eval("#results", (e) => Math.round(e.scrollTop));

  /* 1 — initial load */
  await page.goto(FILE, { waitUntil: "load" });
  await page.waitForSelector("#results .row", { timeout: 5000 });
  await sleep(150);
  rec("1", "data-state", await state());
  rec("1", "counter", await counter());
  rec("1", "activeElement", page.evaluate(() => document.activeElement.id));
  rec("1", "rowsRendered", (await page.$$("#results .row")).length);
  rec("1", "bootOverlayGone", page.evaluate(() => !document.querySelector(".app").classList.contains("is-booting")));
  await shot(page, "01-initial-ready.png");

  /* 2 — search (interaction 1): real keystrokes */
  await page.click("#search");
  await page.keyboard.type("glacier", { delay: 40 });
  await sleep(150);
  rec("2", "counter", await counter());
  rec("2", "firstRowName", page.$eval("#results .row .row-name", (e) => e.textContent));
  rec("2", "marksInFirstRow", page.$$eval("#results .row mark", (m) => m.length));
  rec("2", "atlasVisible", page.$$eval("#results .row .row-name", (ns) => ns.some((n) => /Global Glacier Mass Balance Atlas/.test(n.textContent))));
  await shot(page, "02-search-glacier.png");

  /* 3 — facet (interaction 2) */
  const tagSel = (await page.$('#tag-facets .facet-row[data-tag="climate"]'))
    ? '#tag-facets .facet-row[data-tag="climate"]'
    : '#tag-facets .facet-row[data-tag="raster"]';
  await page.click(tagSel);
  await sleep(150);
  rec("3", "clickedFacet", tagSel);
  rec("3", "counter", await counter());
  rec("3", "chips", await chips());
  await shot(page, "03-facet.png");

  /* 4 — select (interaction 3): detail opens in place */
  const target = await page.evaluate(() => {
    const rows = [...document.querySelectorAll("#results .row")];
    const r = rows.find((x) => /Global Glacier Mass Balance Atlas/.test(x.textContent));
    return r ? { id: r.dataset.id } : null;
  });
  rec("4", "targetRow", target);
  const before4 = { scroll: await scrollTop(), chips: await chips(), counter: await counter() };
  await page.click(`#results .row[data-id="${target.id}"]`);
  await sleep(200);
  rec("4", "detailHidden", page.$eval("#detail", (e) => e.hidden));
  rec("4", "detailName", page.$eval("#d-name", (e) => e.textContent));
  rec("4", "detailId", page.$eval("#d-id", (e) => e.textContent));
  rec("4", "data-state", await state());
  rec("4", "selectedRowAria", page.$eval(`#results .row[data-id="${target.id}"]`, (e) => e.getAttribute("aria-selected")));
  rec("4", "context.scroll", await scrollTop());
  rec("4", "context.chips", await chips());
  rec("4", "context.counter", await counter());
  rec("4", "context.identical", JSON.stringify({ scroll: await scrollTop(), chips: await chips(), counter: await counter() }) === JSON.stringify(before4));
  await shot(page, "04-detail-open.png");

  /* 5 — keyboard path: Esc closes (focus on row, not input) → "/" → type → ↓↓↓ → Enter */
  await page.keyboard.press("Escape"); // focus is on the row (not input) → closes panel
  await sleep(120);
  rec("5", "panelClosedAfterEsc", page.$eval("#detail", (e) => e.hidden));
  await page.keyboard.press("Slash"); // "/" focuses search
  await sleep(80);
  rec("5", "focusAfterSlash", page.evaluate(() => document.activeElement.id));
  await page.keyboard.type("census", { delay: 40 });
  for (let i = 0; i < 3; i++) { await page.keyboard.press("ArrowDown"); await sleep(60); }
  rec("5", "cursorRow", page.$eval("#results .row.cursor", (e) => e.id));
  rec("5", "counter", await counter());
  await page.keyboard.press("Enter");
  await sleep(200);
  rec("5", "detailName", page.$eval("#d-name", (e) => e.textContent));
  rec("5", "detailId", page.$eval("#d-id", (e) => e.textContent));
  rec("5", "data-state", await state());
  rec("5", "cursorHasRing", page.$eval("#results .row.cursor", (e) => getComputedStyle(e).boxShadow !== "none"));
  await shot(page, "05-keyboard-path.png");

  /* 6 — empty state */
  await page.click("#detail-close");
  await sleep(120);
  await page.click("#search", { clickCount: 3 });
  await page.keyboard.type("zzzqqx", { delay: 30 });
  await sleep(150);
  rec("6", "emptyHeading", page.$eval("#empty h2", (e) => e.textContent));
  rec("6", "emptyDetail", page.$eval("#empty-detail", (e) => e.textContent));
  rec("6", "data-state", await state());
  await shot(page, "06-empty.png");
  await page.click("#empty-clear");
  await sleep(150);
  rec("6", "counterAfterClear", await counter());

  /* 7 — error state (bad deep link) */
  await page.goto(FILE + "#sel=DS-99999", { waitUntil: "load" });
  await sleep(200);
  rec("7", "bannerVisible", page.$eval("#error-banner", (e) => !e.hidden));
  rec("7", "bannerText", page.$eval("#error-text", (e) => e.textContent));
  rec("7", "data-state", await state());
  await shot(page, "07-error.png");
  await page.click("#error-reset");
  await sleep(150);
  rec("7", "bannerHiddenAfterReset", page.$eval("#error-banner", (e) => e.hidden));
  rec("7", "counterAfterReset", await counter());

  /* 8 — context preservation under scroll */
  await page.click("#search", { clickCount: 3 });
  await page.keyboard.type("solar", { delay: 30 });
  await sleep(120);
  await page.click('.tree .facet-row[data-cat="energy"]');
  await sleep(150);
  await page.mouse.move(800, 500);
  await page.mouse.wheel({ deltaY: 800 });
  await sleep(150);
  const before8 = { scroll: await scrollTop(), chips: await chips(), counter: await counter() };
  rec("8", "before", before8);
  await shot(page, "08a-before-select.png");
  await page.click("#results .row.cursor");
  await sleep(200);
  const after8 = { scroll: await scrollTop(), chips: await chips(), counter: await counter() };
  rec("8", "after", after8);
