/* Locus — compact professional tokens (P-22 Signal over Chrome, H-13 Structured Density) */
:root {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --surface-2: #f9fafb;
  --line: #e3e8ee;
  --ink: #1a2430;
  --muted: #5c6b7a;
  --faint: #8a97a5;
  --accent: #1a66e0;
  --accent-ink: #0f4db3;
  --accent-bg: #eaf1fd;
  --accent-line: #bcd4f7;
  --mark: #ffe9a8;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --radius: 6px;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font: 13px/1.45 "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }
mark { background: var(--mark); color: inherit; border-radius: 2px; padding: 0 1px; }

.app { height: 100vh; display: flex; flex-direction: column; }
.app.is-booting::after { /* total state model; unreachable in practice (sync boot) */
  content: "Loading collection…"; position: fixed; inset: 0; display: grid; place-items: center;
  background: var(--bg); color: var(--muted);
}

/* ---------- top bar ---------- */
.topbar {
  display: flex; align-items: center; gap: 16px;
  height: 52px; padding: 0 14px;
  background: var(--surface); border-bottom: 1px solid var(--line);
  flex: none;
}
.brand { display: flex; align-items: baseline; gap: 7px; flex: none; color: var(--accent); }
.brand-mark { align-self: center; }
.brand-name { font-size: 15px; font-weight: 700; letter-spacing: .2px; color: var(--ink); }
.brand-sub { font-size: 11px; color: var(--faint); letter-spacing: .6px; text-transform: uppercase; }
.locate {
  position: relative; flex: 1; max-width: 680px;
  display: flex; align-items: center;
}
.locate-icon { position: absolute; left: 11px; color: var(--faint); pointer-events: none; }
.locate-input {
  width: 100%; height: 34px;
  padding: 0 34px 0 32px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface-2);
  font: inherit; color: var(--ink);
}
.locate-input:focus { background: var(--surface); border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px var(--accent-bg); }
.locate-input::placeholder { color: var(--faint); }
.locate-kbd {
  position: absolute; right: 9px;
  font: 11px var(--mono); color: var(--faint);
  border: 1px solid var(--line); border-radius: 4px; padding: 0 5px; background: var(--surface);
}
.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 10px; flex: none; }
.result-count { font-size: 12px; color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }

.btn-ghost {
  height: 26px; padding: 0 9px; border-radius: var(--radius);
  font-size: 12px; color: var(--accent-ink); border: 1px solid var(--accent-line);
  background: var(--surface);
}
.btn-ghost:hover { background: var(--accent-bg); }
.btn-tiny { height: 22px; padding: 0 7px; font-size: 11px; }
.btn {
  height: 30px; padding: 0 14px; border-radius: var(--radius);
  background: var(--accent); color: #fff; font-weight: 600;
}
.btn:hover { background: var(--accent-ink); }

/* ---------- error banner (error state) ---------- */
.error-banner {
  flex: none; display: flex; align-items: center; gap: 12px;
  padding: 8px 14px; background: var(--danger-bg); color: var(--danger);
  border-bottom: 1px solid #f2c4c0; font-weight: 600;
}
.error-banner .btn-ghost { color: var(--danger); border-color: #e4b1ac; background: #fff; }

/* ---------- filter chips ---------- */
.chips {
  flex: none; display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  padding: 7px 14px; background: var(--surface); border-bottom: 1px solid var(--line);
}
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  height: 24px; padding: 0 8px; border-radius: 12px;
  background: var(--accent-bg); border: 1px solid var(--accent-line);
  color: var(--accent-ink); font-size: 12px;
}
.chip:hover { border-color: var(--accent); }
.chip-x { font-size: 10px; opacity: .7; }
.chip:hover .chip-x { opacity: 1; }

/* ---------- workspace ---------- */
.workspace { flex: 1; display: flex; min-height: 0; }

/* ---------- facet rail ---------- */
.rail {
  width: 236px; flex: none; overflow-y: auto;
  background: var(--surface); border-right: 1px solid var(--line);
  padding: 10px 10px 24px;
}
.facet { margin-top: 18px; }
.facet-title {
  margin: 0 0 6px; font-size: 11px; font-weight: 700;
  letter-spacing: .8px; text-transform: uppercase; color: var(--muted);
  display: flex; align-items: baseline; gap: 6px;
}
.facet-note { font-weight: 400; text-transform: none; letter-spacing: 0; color: var(--faint); font-size: 10px; }
.facet-row {
  display: flex; align-items: center; width: 100%; gap: 6px;
  padding: 4px 8px; border-radius: 5px; text-align: left;
  color: var(--ink);
}
.facet-row:hover { background: var(--surface-2); }
.facet-row.on { background: var(--accent-bg); color: var(--accent-ink); font-weight: 600; }
.facet-label { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.facet-n { font-size: 11px; color: var(--faint); font-variant-numeric: tabular-nums; }
.facet-row.on .facet-n { color: var(--accent-ink); }
.facet-none { color: var(--faint); font-size: 12px; padding: 2px 8px; }
.tree-domain { display: flex; align-items: center; }
.tree-domain.on .tree-twist { color: var(--accent-ink); }
.tree-twist {
  flex: none; width: 18px; height: 24px; display: grid; place-items: center;
  color: var(--faint); border-radius: 4px;
}
.tree-twist svg { transition: transform .12s ease; }
.tree-twist[aria-expanded="true"] svg { transform: rotate(90deg); }
.tree-domain .facet-row { flex: 1; font-weight: 600; }
.tree-subcats { margin: 1px 0 3px; }
.show-more { display: block; margin: 4px 8px 0; font-size: 12px; color: var(--accent-ink); }
.show-more:hover { text-decoration: underline; }

/* ---------- results ---------- */
.results-pane { flex: 1; min-width: 0; display: flex; flex-direction: column; background: var(--bg); }
.results {
  flex: 1; overflow-y: auto; position: relative; outline-offset: -2px;
}
.results::before { content: ""; display: block; height: var(--canvas-h, 0); }
.row {
  position: absolute; left: 8px; right: 8px; height: 31px; margin-top: 1px;
  display: flex; align-items: center; gap: 10px;
  padding: 0 10px; border-radius: 5px;
  background: var(--surface); border: 1px solid var(--line);
  cursor: pointer;
}
.row:hover { border-color: var(--accent-line); background: #fdfefe; }
.row.cursor { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.row.selected { background: var(--accent-bg); border-color: var(--accent); }
.row-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.row-id { flex: none; width: 84px; font: 11px var(--mono); color: var(--muted); }
.row-sub { flex: none; width: 170px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); font-size: 12px; }
.row-meta { flex: none; width: 220px; text-align: right; color: var(--faint); font-size: 11px; font-variant-numeric: tabular-nums; }

/* ---------- empty state ---------- */
.empty { flex: 1; display: grid; place-content: center; text-align: center; gap: 8px; padding: 24px; }
.empty[hidden] { display: none; }
.empty-art {
  width: 56px; height: 56px; margin: 0 auto; border-radius: 50%;
  background: var(--surface); border: 1px dashed var(--line); position: relative;
}
.empty-art::after {
  content: ""; position: absolute; inset: 14px; border-radius: 50%;
  border: 6px solid var(--accent-bg);
}
.empty h2 { margin: 4px 0 0; font-size: 16px; }
.empty p { margin: 0; color: var(--muted); max-width: 420px; }
.empty-tip { font-size: 12px; color: var(--faint); }
.empty .btn { justify-self: center; margin-top: 6px; }

/* ---------- detail panel (selection-driven, context-preserving) ---------- */
.detail {
  width: 352px; flex: none; overflow-y: auto;
  background: var(--surface); border-left: 1px solid var(--line);
  padding: 14px 16px 24px;
}
.detail[hidden] { display: none; }
.detail-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.detail-crumb { font-size: 11px; color: var(--faint); letter-spacing: .3px; }
.icon-btn {
  width: 24px; height: 24px; border-radius: 5px; display: grid; place-items: center;
  color: var(--muted); border: 1px solid transparent;
}
.icon-btn:hover { background: var(--surface-2); border-color: var(--line); color: var(--ink); }
.detail-name { margin: 8px 0 6px; font-size: 16px; line-height: 1.3; }
.detail-id-row { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.detail-id { font: 12px var(--mono); color: var(--accent-ink); background: var(--accent-bg); padding: 2px 6px; border-radius: 4px; }
.detail-desc { margin: 0 0 14px; color: var(--ink); }
.detail-meta { margin: 0; display: grid; grid-template-columns: 84px 1fr; row-gap: 6px; column-gap: 10px; font-size: 12px; }
.detail-meta dt { color: var(--faint); }
.detail-meta dd { margin: 0; font-variant-numeric: tabular-nums; }
.detail-tags { margin-top: 14px; display: flex; flex-wrap: wrap; gap: 5px; }
.pill {
  font-size: 11px; color: var(--muted);
  background: var(--surface-2); border: 1px solid var(--line);
  padding: 1px 7px; border-radius: 9px;
}
.detail-context-note {
  margin-top: 18px; padding-top: 10px; border-top: 1px dashed var(--line);
  font-size: 11px; color: var(--faint);
}

/* ---------- scrollbars (subtle) ---------- */
.rail, .results, .detail { scrollbar-width: thin; scrollbar-color: var(--line) transparent; }

