1:import { createHash } from "node:crypto";
2:import { lstat, readdir, readFile, realpath } from "node:fs/promises";
3:import { isAbsolute, join, relative, resolve } from "node:path";
5:export interface ExpectedMeasurementTarget {
6:  appRoot: string;
7:  entry: string;
8:  scenario: string;
9:  sessionId: string | null;
10:}
12:export const CONTRACT_FILES = ["screen.sdir.yaml", "sdir-delta.yaml", "implementation-brief.yaml"] as const;
13:const EXCLUDED = new Set(["node_modules", ".git", ".prax", ".prax-state", "validation-evidence", "coverage", ".vite"]);
14:const MAX_ENTRIES = 50_000;
15:const MAX_BYTES = 256 * 1024 * 1024;
17:export function isMeasurementExcluded(path: string): boolean {
18:  return path.split(/[\\/]/).some((name) => EXCLUDED.has(name.toLowerCase()) || /\.(?:log|tmp|tsbuildinfo)$/i.test(name));
19:}
21:/** Hash sorted names and bytes, not timestamps. Never follow tree symlinks. */
22:export async function captureImplementation(root: string): Promise<{ root: string; digest: string }> {
23:  const canonical = await realpath(root);
24:  if (!(await lstat(canonical)).isDirectory()) throw new Error("Implementation root must be a directory");
25:  const hash = createHash("sha256").update("prax-static-tree-v1\0");
26:  let entries = 0;
27:  let bytes = 0;
28:  async function visit(directory: string, prefix: string): Promise<void> {
29:    const names = (await readdir(directory)).sort();
30:    for (const name of names) {
31:      if (++entries > MAX_ENTRIES) throw new Error("Implementation tree exceeds entry limit");
32:      if (isMeasurementExcluded(name)) continue;
33:      const path = join(directory, name);
34:      const stats = await lstat(path);
35:      if (stats.isSymbolicLink()) throw new Error(`Implementation tree contains a symlink: ${prefix}${name}`);
36:      if (stats.isDirectory()) {
37:        await visit(path, `${prefix}${name}/`);
38:      } else if (stats.isFile()) {
39:        bytes += stats.size;
40:        if (bytes > MAX_BYTES) throw new Error("Implementation tree exceeds byte limit");
41:        const content = await readFile(path);
42:        if (content.length !== stats.size) throw new Error("Implementation file changed while hashing");
43:        hash.update(JSON.stringify([`${prefix}${name}`, content.length]));
44:        hash.update("\0").update(content).update("\0");
45:      } else {
46:        throw new Error(`Implementation tree contains a non-regular file: ${prefix}${name}`);
47:      }
48:    }
49:  }
50:  await visit(canonical, "");
51:  return { root: canonical, digest: hash.digest("hex") };
52:}
54:export async function captureContracts(sessionDirectory: string): Promise<Record<string, string | null>> {
55:  const result: Record<string, string | null> = {};
56:  for (const name of CONTRACT_FILES) {
57:    try {
58:      const path = join(sessionDirectory, name);
59:      const stats = await lstat(path);
60:      if (!stats.isFile() || stats.isSymbolicLink()) throw new Error(`Contract is not a regular file: ${name}`);
61:      if (stats.size > MAX_BYTES) throw new Error(`Contract exceeds byte limit: ${name}`);
62:      result[name] = createHash("sha256").update(await readFile(path)).digest("hex");
63:    } catch (error) {
64:      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
65:      result[name] = null;
66:    }
67:  }
68:  return result;
69:}
71:export async function resolveMeasurementTarget(
72:  projectRoot: string,
73:  target: { app_root: string; entry: string; scenario: string },
74:  sessionId: string,
75:): Promise<ExpectedMeasurementTarget> {
76:  if (isAbsolute(target.app_root) || /^[a-z]:/i.test(target.app_root)) throw new Error("measurement_target.app_root must be project-relative");
77:  if (!target.entry.startsWith("/") || target.entry.startsWith("//") || /[\\\s]/.test(target.entry)) throw new Error("measurement_target.entry must be a root-relative URL path");
78:  if (!target.scenario.trim()) throw new Error("measurement_target.scenario is required");
79:  const project = await realpath(projectRoot);
80:  const appRoot = await realpath(resolve(project, target.app_root));
81:  const rel = relative(project, appRoot);
82:  if (rel === ".." || rel.startsWith(`..\\`) || rel.startsWith("../") || isAbsolute(rel)) throw new Error("measurement_target.app_root escapes project root");
83:  if (!(await lstat(appRoot)).isDirectory()) throw new Error("measurement_target.app_root must be a directory");
84:  return { appRoot, entry: target.entry, scenario: target.scenario, sessionId };
85:}

