109	
110	// Severity at birth per ADR-005 decision 6: checks are warning-born, the two
111	// WCAG normative checks are error-born (zero overkill risk). PROMOTED to
112	// error on 2026-09-02 after zero-overkill calibration on every runnable
113	// golden app (landing/dashboard/wizard — Phase 4 F5, the first accreting-gate
114	// instance, spec §8.1): layout.overflow, layout.responsive_collision,
115	// text.truncation, a11y.focus_order. type.min_projected_size stays warning —
116	// spec §5.3 pins it advisory (density-linked thresholds deferred).
117	export const ARTIFACT_CHECK_DEFAULT_SEVERITY: Record<ArtifactCheckId, "warning" | "error"> = {
118	  "layout.overflow": "error",
119	  "layout.responsive_collision": "error",
120	  "text.truncation": "error",
121	  "a11y.contrast": "error",
122	  "a11y.focus_order": "error",
