127	// Spec §5.4: validator check id -> measured catalog ids it accepts receipts for.
128	// Lookup semantics: absent key ≡ empty mapping (not enforced).
129	export const CHECK_MEASUREMENT_MAP: Record<string, readonly ArtifactCheckId[]> = {
130	  readability: ["a11y.contrast", "type.min_projected_size"],
131	  keyboard: ["a11y.focus_order"],
132	  regression_check: ["layout.overflow"],
