137	  id: z.enum(ARTIFACT_CHECK_IDS),
138	  status: z.enum(["pass", "fail", "skipped"]),
139	  severity: z.enum(["warning", "error"]),
140	  subject: NonEmpty.optional(),
141	  measured: z.record(z.string(), z.unknown()).default({}),
142	  threshold: z.record(z.string(), z.unknown()).default({}),
143	  evidence_refs: z
144	    .array(z.object({
145	      ref: NonEmpty.refine((r) => r.startsWith("validation-evidence/"), {
146	        message: "receipt evidence refs must live under validation-evidence/",
147	      }),
