149	    }))
150	    .default([]),
151	  supported_fixes: z.array(NonEmpty).default([]),
152	  reason: NonEmpty.optional(),
153	}).superRefine((check, ctx) => {
154	  if (check.status === "skipped" && check.reason === undefined) {
155	    ctx.addIssue({ code: "custom", message: "skipped checks require a reason" });
156	  }
157	  if (check.status !== "pass" && check.subject === undefined) {
158	    ctx.addIssue({ code: "custom", message: "fail/skipped checks require a subject" });
159	  }
160	});
