179	  receipt_version: z.literal("0.2"),
180	  binding: z.object({
181	    run_id: NonEmpty,
182	    entry: NonEmpty.refine((entry) => entry.startsWith("/") && !entry.startsWith("//") && !/[\\\s]/.test(entry)),
183	    scenario: NonEmpty,
