export const ARTIFACT_CHECK_IDS = [
  "layout.overflow",
  "layout.responsive_collision",
  "text.truncation",
  "a11y.contrast",
  "a11y.focus_order",
  "a11y.target_size",
  "type.min_projected_size",
] as const;
export type ArtifactCheckId = (typeof ARTIFACT_CHECK_IDS)[number];

// Severity at birth per ADR-005 decision 6: checks are warning-born, the two
// WCAG normative checks are error-born (zero overkill risk). PROMOTED to
// error on 2026-09-02 after zero-overkill calibration on every runnable
// golden app (landing/dashboard/wizard — Phase 4 F5, the first accreting-gate
// instance, spec §8.1): layout.overflow, layout.responsive_collision,
// text.truncation, a11y.focus_order. type.min_projected_size stays warning —
// spec §5.3 pins it advisory (density-linked thresholds deferred).
export const ARTIFACT_CHECK_DEFAULT_SEVERITY: Record<ArtifactCheckId, "warning" | "error"> = {
  "layout.overflow": "error",
  "layout.responsive_collision": "error",
  "text.truncation": "error",
  "a11y.contrast": "error",
  "a11y.focus_order": "error",
  "a11y.target_size": "error",
  "type.min_projected_size": "warning",
};

// Spec §5.4: validator check id -> measured catalog ids it accepts receipts for.
// Lookup semantics: absent key ≡ empty mapping (not enforced).
export const CHECK_MEASUREMENT_MAP: Record<string, readonly ArtifactCheckId[]> = {
  readability: ["a11y.contrast", "type.min_projected_size"],
  keyboard: ["a11y.focus_order"],
  regression_check: ["layout.overflow"],
  untouched_surface_regression: ["layout.overflow", "layout.responsive_collision"],
};

export const MeasurementReceiptCheckSchema = z.object({
  id: z.enum(ARTIFACT_CHECK_IDS),
  status: z.enum(["pass", "fail", "skipped"]),
  severity: z.enum(["warning", "error"]),
  subject: NonEmpty.optional(),
  measured: z.record(z.string(), z.unknown()).default({}),
  threshold: z.record(z.string(), z.unknown()).default({}),
  evidence_refs: z
    .array(z.object({
      ref: NonEmpty.refine((r) => r.startsWith("validation-evidence/"), {
        message: "receipt evidence refs must live under validation-evidence/",
      }),
      sha256: z.string().regex(/^[0-9a-f]{64}$/),
    }))
    .default([]),
  supported_fixes: z.array(NonEmpty).default([]),
  reason: NonEmpty.optional(),
}).superRefine((check, ctx) => {
  if (check.status === "skipped" && check.reason === undefined) {
    ctx.addIssue({ code: "custom", message: "skipped checks require a reason" });
  }
  if (check.status !== "pass" && check.subject === undefined) {
    ctx.addIssue({ code: "custom", message: "fail/skipped checks require a subject" });
  }
});
export type MeasurementReceiptCheck = z.infer<typeof MeasurementReceiptCheckSchema>;

export const LegacyMeasurementReceiptSchema = z.object({
  receipt_version: z.literal("0.1"),
  tool: z.object({ name: z.literal("prax-measure"), version: NonEmpty }), // version deliberately NonEmpty, not semver-constrained
  target: z.object({ app_root: NonEmpty, base_url: NonEmpty, build_ref: NonEmpty.nullable() }),
  run_at: z.string().datetime(),
  viewport_matrix: z.array(z.object({ width: z.number().int().positive(), height: z.number().int().positive(), label: NonEmpty.optional() })).min(1),
  checks: z.array(MeasurementReceiptCheckSchema).min(1),
  summary: z.object({ pass: z.number().int().nonnegative(), fail: z.number().int().nonnegative(), skipped: z.number().int().nonnegative(), warnings: z.number().int().nonnegative() }),
});
const Sha256 = z.string().regex(/^[0-9a-f]{64}$/);
export const MeasurementTargetSchema = z.object({
  app_root: NonEmpty.describe("Implementation directory relative to the session project root."),
  entry: NonEmpty.refine((entry) => entry.startsWith("/") && !entry.startsWith("//") && !/[\\\s]/.test(entry), "entry must be a root-relative URL path"),
  scenario: NonEmpty.describe("Declared scenario label; not proof of an executed user journey."),
});
export const BoundMeasurementReceiptSchema = LegacyMeasurementReceiptSchema.extend({
  receipt_version: z.literal("0.2"),
  binding: z.object({
    run_id: NonEmpty,
    entry: NonEmpty.refine((entry) => entry.startsWith("/") && !entry.startsWith("//") && !/[\\\s]/.test(entry)),
    scenario: NonEmpty,
    implementation: z.object({ root: NonEmpty, digest: Sha256, kind: z.enum(["static_tree", "local_source_association"]) }),
    session_id: NonEmpty.nullable(),
    contract_digests: z.object({
      "screen.sdir.yaml": Sha256.nullable(),
      "sdir-delta.yaml": Sha256.nullable(),
      "implementation-brief.yaml": Sha256.nullable(),
    }),
  }),
  target_validation: z.object({
    status: z.enum(["valid", "invalid"]),
    issues: z.array(NonEmpty),
    readiness: z.enum(["document", "selector"]),
    ready_selector: NonEmpty.nullable(),
  }),
});
export const MeasurementReceiptSchema = z.discriminatedUnion("receipt_version", [LegacyMeasurementReceiptSchema, BoundMeasurementReceiptSchema]);
export type MeasurementReceipt = z.infer<typeof MeasurementReceiptSchema>;
export type MeasurementBindingStatus = "legacy_unbound" | "unverified_target" | "implementation_current" | "association_current" | "invalid";

