55	export function lifecyclePolicyFor(mode: DesignMode, changeKind?: ChangeKind): LifecyclePolicy {
56	  if (mode === "greenfield") {
57	    if (changeKind !== undefined) {
58	      throw new PraxRuntimeError(
59	        "UNKNOWN_LIFECYCLE_POLICY",
60	        `change_kind ${changeKind} is not valid for greenfield sessions.`,
61	      );
62	    }
63	    return { version: "2", mode, gates: ["confirm", "framing", ...FULL_TAIL] };
64	  }
65	  if (mode === "existing_product") {
66	    if (changeKind === undefined) {
67	      throw new PraxRuntimeError(
68	        "UNKNOWN_LIFECYCLE_POLICY",
69	        "existing_product sessions require change_kind (add_surface | modify_surface | visual_polish | defect_fix).",
70	      );
71	    }
72	    const gatesByKind: Record<ChangeKind, GateName[]> = {
73	      add_surface: ["confirm", "understanding", "framing", ...FULL_TAIL],
74	      modify_surface: ["confirm", "understanding", "route", "decide", "sdir_delta", "prepare", "validate"],
75	      visual_polish: ["confirm", "understanding", "intent_lite", "validate"],
76	      defect_fix: ["confirm", "understanding", "intent_lite", "validate"],
77	    };
78	    return { version: "2", mode, change_kind: changeKind, gates: gatesByKind[changeKind] };
79	  }
80	  return {
81	    version: "2",
82	    mode,
83	    ...(changeKind === undefined ? {} : { change_kind: changeKind }),
84	    gates: ["confirm", "understanding", "framing", ...REWORK_TAIL],
85	  };
86	}
